public class JacksonAnnotationIntrospector_findObjectIdInfo_TriageGen2Test {

    private JacksonAnnotationIntrospector introspector;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    /**
     * Test case: Annotated object has no JsonIdentityInfo annotation.
     * Expected: returns null.
     */
    @Test
    public void testFindObjectIdInfo_NoAnnotation() {
        Annotated mockAnnotated = mock(Annotated.class);
        // By default, _findAnnotation will return null if not mocked or if no annotation is present
        // Since we can't easily mock the protected _findAnnotation behavior without a spy, 
        // we use a real scenario or mock the behavior if possible. 
        // However, JacksonAnnotationIntrospector is a concrete class.

        // We simulate the absence of annotation by providing an annotated object that has none.
        ObjectIdInfo result = introspector.findObjectIdInfo(mockAnnotated);
        assertNull(result);
    }

    /**
     * Test case: JsonIdentityInfo is present but the generator is ObjectIdGenerators.None.
     * Expected: returns null.
     */
    @Test
    public void testFindObjectIdInfo_WithNoneGenerator() throws Exception {
        Annotated mockAnnotated = mock(Annotated.class);

        // We need to mock the behavior of _findAnnotation. Since it's protected, 
        // we use a spy to force the return value of _findAnnotation.
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        JsonIdentityInfo noneInfo = mock(JsonIdentityInfo.class);
        when(noneInfo.generator()).thenReturn(ObjectIdGenerators.None.class);

        doReturn(noneInfo).when(spyIntrospector)._findAnnotation(eq(mockAnnotated), eq(JsonIdentityInfo.class));

        ObjectIdInfo result = spyIntrospector.findObjectIdInfo(mockAnnotated);
        assertNull(result);
    }

    /**
     * Test case: JsonIdentityInfo is present with a valid generator (not None).
     * Expected: returns a valid ObjectIdInfo object with correct properties.
     */
    @Test
    public void testFindObjectIdInfo_WithValidGenerator() throws Exception {
        Annotated mockAnnotated = mock(Annotated.class);
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        String propertyNameStr = "id";
        Class<?> generatorClass = ObjectIdGenerators.IntSequenceGenerator.class;
        Class<?> scopeClass = Object.class;
        // Note: resolver is often null in simple annotations

        JsonIdentityInfo validInfo = mock(JsonIdentityInfo.class);
        when(validInfo.property()).thenReturn(propertyNameStr);
        when(validInfo.generator()).thenReturn(generatorClass);
        when(validInfo.scope()).thenReturn(scopeClass);
        when(validInfo.resolver()).thenReturn(null);

        doReturn(validInfo).when(spyIntrospector)._findAnnotation(eq(mockAnnotated), eq(JsonIdentityInfo.class));

        ObjectIdInfo result = spyIntrospector.findObjectIdInfo(mockAnnotated);

        assertNotNull(result);
        assertEquals(PropertyName.construct(propertyNameStr), result.getName());
        assertEquals(scopeClass, result.getScope());
        assertEquals(generatorClass, result.getGenerator());
        assertNull(result.getResolver());
    }

    /**
     * Test case: JsonIdentityInfo is present, generator is valid, and resolver is provided.
     * Expected: returns ObjectIdInfo with the resolver.
     */
    @Test
    public void testFindObjectIdInfo_WithResolver() throws Exception {
        Annotated mockAnnotated = mock(Annotated.class);
        JacksonAnnotationIntrospector spyIntrospector = spy(new JacksonAnnotationIntrospector());

        ObjectIdResolver mockResolver = mock(ObjectIdResolver.class);
        JsonIdentityInfo validInfo = mock(JsonIdentityInfo.class);
        when(validInfo.property()).thenReturn("ref");
        when(validInfo.generator()).thenReturn(ObjectIdGenerators.PrimeGenerator.class);
        when(validInfo.scope()).thenReturn(Object.class);
        when(validInfo.resolver()).thenReturn(mockResolver);

        doReturn(validInfo).when(spyIntrospector)._findAnnotation(eq(mockAnnotated), eq(JsonIdentityInfo.class));

        ObjectIdInfo result = spyIntrospector.findObjectIdInfo(mockAnnotated);

        assertNotNull(result);
        assertEquals(mockResolver, result.getResolver());
    }
}
